117→func configureDroidRepoSettings(repoDir string) error {
118→	home, err := os.UserHomeDir()
119→	if err != nil {
120→		return fmt.Errorf("get home dir: %w", err)
121→	}
122→
123→	globalSettingsPath := filepath.Join(home, ".factory", "settings.json")
124→	repoSettingsPath := filepath.Join(repoDir, droidRepoSettingsPath)
125→
126→	if err := mergeDroidCustomModels(globalSettingsPath, repoSettingsPath); err != nil {
127→		return err
128→	}
129→	if err := ensureGitInfoExcludeContains(repoDir, droidRepoSettingsPath); err != nil {
130→		return fmt.Errorf("exclude droid settings from git: %w", err)
131→	}
132→	return nil
133→}
134→
135→func mergeDroidCustomModels(globalSettingsPath, repoSettingsPath string) error {
136→	globalSettings, err := loadJSONMap(globalSettingsPath, "global droid settings")
137→	if err != nil {
138→		return err
139→	}
140→
141→	customModels, ok := globalSettings["customModels"]
142→	if !ok {
143→		return fmt.Errorf(
144→			"global droid settings at %s missing customModels; repo-local %s shadows global settings",
145→			globalSettingsPath,
146→			repoSettingsPath,
147→		)
148→	}
149→
150→	var models []json.RawMessage
151→	if err := json.Unmarshal(customModels, &models); err != nil {
152→		return fmt.Errorf("parse customModels in %s: %w", globalSettingsPath, err)
153→	}
154→	if len(models) == 0 {
155→		return fmt.Errorf("global droid settings at %s has empty customModels", globalSettingsPath)
156→	}
157→
158→	repoSettings, err := loadJSONMap(repoSettingsPath, "repo-local droid settings")
159→	if err != nil {
160→		return err
161→	}
162→	repoSettings["customModels"] = customModels
163→
164→	out, err := json.MarshalIndent(repoSettings, "", "  ")
165→	if err != nil {
166→		return fmt.Errorf("marshal repo-local droid settings: %w", err)
167→	}
168→	out = append(out, '\n')
169→
170→	if err := os.WriteFile(repoSettingsPath, out, 0o600); err != nil {
171→		return fmt.Errorf("write repo-local droid settings %s: %w", repoSettingsPath, err)
172→	}
173→	return nil
174→}
