386→// PatchSettings merges extra keys into .entire/settings.json.
387→func PatchSettings(t *testing.T, dir string, extra map[string]any) {
388→	t.Helper()
389→	path := filepath.Join(dir, ".entire", "settings.json")
390→	data, err := os.ReadFile(path)
391→	if err != nil {
392→		t.Fatalf("read settings: %v", err)
393→	}
394→	var settings map[string]any
395→	if err := json.Unmarshal(data, &settings); err != nil {
396→		t.Fatalf("parse settings: %v", err)
397→	}
398→	for k, v := range extra {
399→		settings[k] = v
400→	}
401→	out, err := json.MarshalIndent(settings, "", "  ")
402→	if err != nil {
403→		t.Fatalf("marshal settings: %v", err)
404→	}
405→	if err := os.WriteFile(path, out, 0o644); err != nil {
406→		t.Fatalf("write settings: %v", err)
407→	}
408→}
