410→// Git runs a git command in the given directory and fails the test if it
411→// returns a non-zero exit code.
412→func Git(t *testing.T, dir string, args ...string) {
413→	t.Helper()
414→
415→	cmd := exec.Command("git", args...)
416→	if dir != "" {
417→		cmd.Dir = dir
418→	}
419→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
420→
421→	out, err := cmd.CombinedOutput()
422→	if err != nil {
423→		t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, out)
424→	}
425→}
