427→// GitOutput runs a git command in the given directory, returns its trimmed
428→// stdout, and fails the test on error.
429→func GitOutput(t *testing.T, dir string, args ...string) string {
430→	t.Helper()
431→
432→	cmd := exec.Command("git", args...)
433→	if dir != "" {
434→		cmd.Dir = dir
435→	}
436→
437→	out, err := cmd.Output()
438→	if err != nil {
439→		var stderr string
440→		ee := &exec.ExitError{}
441→		if errors.As(err, &ee) {
442→			stderr = string(ee.Stderr)
443→		}
444→		t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, stderr)
445→	}
446→
447→	return strings.TrimSpace(string(out))
448→}
