450→// NewCheckpointCommits returns the SHAs of commits added to the
451→// entire/checkpoints/v1 branch since the test was set up, oldest first.
452→func NewCheckpointCommits(t *testing.T, s *RepoState) []string {
453→	t.Helper()
454→
455→	log := GitOutput(t, s.Dir, "log", "--reverse", "--format=%H", s.CheckpointBefore+"..entire/checkpoints/v1")
456→	if log == "" {
457→		return nil
458→	}
459→	return strings.Split(log, "\n")
