462→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
463→// checkpoint branch. It parses the two-level directory structure
464→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
465→func CheckpointIDs(t *testing.T, dir string) []string {
466→	t.Helper()
467→	out := gitOutputSafe(dir, "ls-tree", "-r", "--name-only", "entire/checkpoints/v1")
468→	if out == "" {
469→		return nil
470→	}
471→	seen := map[string]bool{}
472→	var ids []string
473→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
474→		// Match {prefix}/{suffix}/metadata.json (top-level, not session-level)
475→		parts := strings.Split(line, "/")
476→		if len(parts) == 3 && parts[2] == "metadata.json" {
477→			id := parts[0] + parts[1]
478→			if !seen[id] {
479→				seen[id] = true
480→				ids = append(ids, id)
481→			}
482→		}
483→	}
484→	return ids
485→}
