523→// WaitForSessionMetadata polls until session metadata exists on the checkpoint
524→// branch for the given checkpoint ID and session index, then returns it.
525→// This handles the race where the checkpoint branch advances before session
526→// metadata is fully committed.
527→func WaitForSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int, timeout time.Duration) SessionMetadata {
528→	t.Helper()
529→
530→	path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
531→	blob := "entire/checkpoints/v1:" + path
532→
533→	deadline := time.Now().Add(timeout)
534→	for time.Now().Before(deadline) {
535→		raw := gitOutputSafe(dir, "show", blob)
536→		if raw != "" {
537→			var meta SessionMetadata
538→			if err := json.Unmarshal([]byte(raw), &meta); err != nil {
539→				t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
540→			}
541→			return meta
542→		}
543→		time.Sleep(500 * time.Millisecond)
544→	}
545→	t.Fatalf("session metadata %s did not appear within %s", blob, timeout)
546→	return SessionMetadata{}
547→}
