549→// SetupBareRemote creates a bare git repo, adds it as "origin", and pushes
550→// the initial commit. Returns the bare repo path.
551→func SetupBareRemote(t *testing.T, s *RepoState) string {
552→	t.Helper()
553→
554→	var bareDir string
555→	if os.Getenv("E2E_KEEP_REPOS") != "" {
556→		var err error
557→		bareDir, err = os.MkdirTemp("", "e2e-bare-*")
558→		if err != nil {
559→			t.Fatalf("create bare remote dir: %v", err)
560→		}
561→		t.Logf("E2E_KEEP_REPOS: bare remote will be preserved at %s", bareDir)
562→	} else {
563→		bareDir = t.TempDir()
564→	}
565→
566→	Git(t, bareDir, "init", "--bare")
567→	Git(t, s.Dir, "remote", "add", "origin", bareDir)
568→	Git(t, s.Dir, "push", "-u", "origin", "HEAD")
569→	return bareDir
570→}
