// WaitFor waits for a pattern in the interactive session's pane and logs the
// pane content to ConsoleLog after the wait completes (success or failure).
func (s *RepoState) WaitFor(t *testing.T, session agents.Session, pattern string, timeout time.Duration) {
	t.Helper()
	scaled := time.Duration(float64(timeout) * s.Agent.TimeoutMultiplier())
	content, err := session.WaitFor(pattern, scaled)
	fmt.Fprintf(s.ConsoleLog, "> pane after WaitFor(%q):\n%s\n", pattern, content)
	if err != nil {
		if s.shouldRetryPromptTimeout(pattern) {
			retryInput := s.lastSentInput
			s.lastSentInput = "" // clear to prevent infinite retries
			t.Logf("WaitFor(%q) timed out; retrying last prompt for droid", pattern)
			fmt.Fprintf(s.ConsoleLog, "> [retry] re-sending %q after prompt timeout\n", retryInput)
			if sendErr := session.Send(retryInput); sendErr != nil {
				t.Fatalf("retry send failed: %v (original WaitFor error: %v)", sendErr, err)
			}
			content, err = session.WaitFor(pattern, scaled)
			fmt.Fprintf(s.ConsoleLog, "> pane after retry WaitFor(%q):\n%s\n", pattern, content)
		}
		if err != nil {
			t.Fatalf("WaitFor(%q): %v", pattern, err)
		}
	}
}

// shouldRetryPromptTimeout returns true when a WaitFor timeout should be
// retried by re-sending the last prompt. This applies only to Droid sessions
// waiting for the prompt pattern after a prompt was previously sent.
func (s *RepoState) shouldRetryPromptTimeout(pattern string) bool {
	return s.Agent.Name() == "factoryai-droid" &&
		pattern == s.Agent.PromptPattern() &&
		s.lastSentInput != ""
}

